parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "route": {
      "type": "string",
      "enum": ["answer", "to_agent_3"],
      "description": "answer - обычный ответ клиенту, эскалация не нужна; to_agent_3 - антифрод-удержание, кейс передаётся Агенту 3"
    },
    "client_reply": {
      "type": "string",
      "description": "Текст для клиента. При route=answer это полный ответ по существу. При route=to_agent_3 короткое сообщение о проверке безопасности и передаче специалисту, без слова мошенничество. Обычный текст без markdown"
    },
    "staff_package": {
      "type": "string",
      "description": "Сводка для Агента 3 при передаче: номер перевода, сумма, валюта, получатель, дата, статус, признак антифрод-удержания, client_id, card_id, что сделано с картой. При route=answer пустая строка"
    },
    "card_action": {
      "type": "string",
      "enum": ["blocked", "already_blocked", "no_action"],
      "description": "blocked - карта заблокирована этим агентом; already_blocked - была заблокирована ранее; no_action - карта не трогалась"
    },
    "card_id": {
      "type": "string",
      "description": "Идентификатор карты, с которой работали. Пустая строка, если карта не затрагивалась"
    },
    "transfer_id": {
      "type": "string",
      "description": "Идентификатор разбираемого перевода. Пустая строка, если перевод не найден"
    }
  },
  "required": ["route", "client_reply", "staff_package", "card_action", "card_id", "transfer_id"]
}

assignments.value:
={{ "ПЕРЕДАЧА ОТ АГЕНТА 2. Обращение поступило как вопрос по операции, при разборе обнаружено антифрод-удержание.

" + $json.output.staff_package + "

Действие Агента 2 с картой: " + $json.output.card_action + " (card_id: " + $json.output.card_id + ")" }}

