parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "hitl_reason": {
      "type": "string",
      "enum": ["h1", "h2", "h3", "h5"],
      "description": "Условие эскалации по таблице HITL. h1 - клиент заявляет о несанкционированном списании; h2 - сработал красный флаг политики; h3 - антифрод-удержание по переводу; h5 - личность не подтверждена"
    },
    "staff_package": {
      "type": "string",
      "description": "Сводка для сотрудника банка: результат проверки личности, номер карты, спорные транзакции с суммами и датами, antifraud_score, сработавшие правила, предварительная классификация, что сделано с картой. Обычный текст без markdown"
    },
    "draft_reply": {
      "type": "string",
      "description": "Черновик содержательного ответа клиенту для сотрудника: он его подтвердит, изменит или заменит. Без обещаний сроков, сумм и без вердикта о мошенничестве. Обычный текст без markdown"
    },
    "card_action": {
      "type": "string",
      "enum": ["blocked", "already_blocked", "no_action"],
      "description": "blocked - карта заблокирована этим агентом; already_blocked - карта была заблокирована ранее; no_action - признаков хищения нет, статус не менялся"
    }
  },
  "required": ["hitl_reason", "staff_package", "draft_reply", "card_action"]
}

